#include <stdint.h>
#include <stdio.h>

// Mandated by the environment
extern volatile uint64_t tohost;
static uint64_t _stack[512];
static uint64_t *const _stack_top = _stack + 512;

// Arrays to store results
#define NUM_TRIALS 20
uint64_t results_control_baseline[NUM_TRIALS];         // Attacker primes P, probes P (expected fast)
uint64_t results_attack_corrupt[NUM_TRIALS];           // Attacker primes P, Victim corrupts to M, Attacker probes P (expected slow)
uint64_t results_control_no_corruption[NUM_TRIALS];    // Attacker primes P, Victim runs P, Attacker probes P (expected fast)
uint64_t results_positive_control_mispredict[NUM_TRIALS]; // Attacker primes P, Attacker forces mispredict to X, Attacker probes P (expected slow)


// Loop function - designed to have a branch instruction whose target is itself
// and whose branch instruction is at a fixed address.
// The 'volatile' keyword and 'target_var' are used to discourage excessive compiler optimizations
// that might remove the loop or change its branch behavior.
__attribute__((noinline))
void run_loop(volatile int iterations, volatile uint64_t *target_var) {
    // Using inline assembly to ensure a branch instruction and prevent excessive unrolling.
    // 't0' and 't1' are temporary registers.
    // '1:' is a local label used by 'bnez t0, 1b' to branch backward.
    asm volatile (
        "mv t0, %0
" // t0 = iterations
        "mv t1, %1
" // t1 = target_var address
        "1:
"        // Loop start label
        "addi t0, t0, -1
" // iterations--
        "sd t0, 0(t1)
"    // Store t0 to target_var (to prevent optimization/removal)
        "bnez t0, 1b
"   // Branch back to 1: if t0 != 0
        : // No output operands
        : "r"(iterations), "r"(target_var) // Input operands: iterations, address of target_var
        : "t0", "t1", "memory" // Clobbered registers and memory
    );
}

// Trap handler placeholder (required by environment)
// This is a minimal trap handler that simply advances the program counter and returns.
// No traps are expected in this experiment, but it's essential for a valid bare-metal program.
__attribute__((naked))
void trap_handler() {
    asm volatile(
        "csrr t0, mepc
"          // Read Machine Exception Program Counter
        "addi t0, t0, 4
"         // Advance MEPC past the instruction that caused the trap (e.g., ecall)
        "csrw mepc, t0
"          // Write updated MEPC back
        "mret
"                   // Return from machine mode
    );
}

// Main function where the experiment is orchestrated
int main() {
    // Set up trap handler address in MTVEC CSR
    asm volatile("csrw mtvec, %0" : : "r"(&trap_handler));

    volatile uint64_t dummy_var = 0; // Used in run_loop to ensure memory access and prevent optimization

    // Attacker's prime and probe loop iterations (P)
    const int ATTACKER_PRIME_ITERS = 20;
    const int ATTACKER_PROBE_ITERS = 20;

    // Victim's loop iterations for different scenarios (M)
    const int VICTIM_CORRUPT_ITERS = 5;  // M != P, expected to corrupt S-counter
    const int VICTIM_NO_CORRUPT_ITERS = 20; // M == P, expected NOT to corrupt S-counter for attacker's probe

    // For the explicit positive control, force a very different misprediction (X)
    const int FORCED_MISPREDICTION_ITERS = 2; // X != P, used to guarantee a misprediction

    printf("Starting LPSC experiment (Loop Predictor State Corruption)...
");
    printf("-------------------------------------------------------------------
");
    printf("Configuration:
");
    printf("Attacker Prime/Probe Iterations (P): %d
", ATTACKER_PRIME_ITERS);
    printf("Victim Corrupting Iterations (M): %d
", VICTIM_CORRUPT_ITERS);
    printf("Victim Non-Corrupting Iterations (P): %d
", VICTIM_NO_CORRUPT_ITERS);
    printf("Forced Misprediction Iterations (X, for Pos Control): %d
", FORCED_MISPREDICTION_ITERS);
    printf("Number of Trials: %d
", NUM_TRIALS);
    printf("-------------------------------------------------------------------
");


    for (int i = 0; i < NUM_TRIALS; i++) {
        // --- 1. Negative Control (Baseline: Attacker primes P, probes P) ---
        // Description: Attacker establishes its expected loop trip count (P) in the predictor, then probes.
        // Expected outcome: FAST (loop predictor should predict correctly).
        run_loop(ATTACKER_PRIME_ITERS, &dummy_var); // Prime the predictor with P
        uint64_t start_cycle, end_cycle;
        asm volatile("rdcycle %0" : "=r"(start_cycle));
        run_loop(ATTACKER_PROBE_ITERS, &dummy_var); // Probe, expecting P
        asm volatile("rdcycle %0" : "=r"(end_cycle));
        results_control_baseline[i] = end_cycle - start_cycle;

        // --- 2. Attack Scenario (Attacker primes P, Victim corrupts to M, Attacker probes P) ---
        // Description: Attacker primes with P. Victim runs M (M != P), corrupting the S-counter. Attacker probes.
        // Expected outcome: SLOW (attacker's probe mispredicts due to victim's corruption).
        run_loop(ATTACKER_PRIME_ITERS, &dummy_var); // Prime with P
        run_loop(VICTIM_CORRUPT_ITERS, &dummy_var); // Victim execution, corrupts S-counter to M
        asm volatile("rdcycle %0" : "=r"(start_cycle));
        run_loop(ATTACKER_PROBE_ITERS, &dummy_var); // Probe, expecting P, but S-counter is M
        asm volatile("rdcycle %0" : "=r"(end_cycle));
        results_attack_corrupt[i] = end_cycle - start_cycle;

        // --- 3. Negative Control (No Corruption: Attacker primes P, Victim runs P, Attacker probes P) ---
        // Description: Attacker primes with P. Victim runs P (same as attacker), should not corrupt S-counter. Attacker probes.
        // Expected outcome: FAST (victim's execution reinforces attacker's prediction).
        run_loop(ATTACKER_PRIME_ITERS, &dummy_var); // Prime with P
        run_loop(VICTIM_NO_CORRUPT_ITERS, &dummy_var); // Victim execution, reinforces S-counter to P
        asm volatile("rdcycle %0" : "=r"(start_cycle));
        run_loop(ATTACKER_PROBE_ITERS, &dummy_var); // Probe, expecting P, and S-counter is P
        asm volatile("rdcycle %0" : "=r"(end_cycle));
        results_control_no_corruption[i] = end_cycle - start_cycle;

        // --- 4. Positive Control (Deliberate Misprediction: Attacker primes P, forces S-counter to X, probes P) ---
        // Description: Attacker primes with P. Attacker then runs X (X != P), explicitly forcing misprediction for next probe.
        // Expected outcome: SLOW (demonstrates that mispredictions are measurable).
        run_loop(ATTACKER_PRIME_ITERS, &dummy_var); // Prime S-counter to P
        run_loop(FORCED_MISPREDICTION_ITERS, &dummy_var); // Force S-counter to X (very different)
        asm volatile("rdcycle %0" : "=r"(start_cycle));
        run_loop(ATTACKER_PROBE_ITERS, &dummy_var); // Probe, expecting P, but S-counter is X. Should mispredict.
        asm volatile("rdcycle %0" : "=r"(end_cycle));
        results_positive_control_mispredict[i] = end_cycle - start_cycle;
    }


    // ---- PRINT RAW RESULTS ----
    printf("
--- Raw results (cycles per trial) ---
");

    printf("
Negative Control (Baseline: Attacker primes %d, probes %d):
", ATTACKER_PRIME_ITERS, ATTACKER_PROBE_ITERS);
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_control_baseline[i]);
    }

    printf("
Attack Scenario (Attacker primes %d, Victim %d, Probes %d):
", ATTACKER_PRIME_ITERS, VICTIM_CORRUPT_ITERS, ATTACKER_PROBE_ITERS);
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_attack_corrupt[i]);
    }

    printf("
Negative Control (No Corruption: Attacker primes %d, Victim %d, Probes %d):
", ATTACKER_PRIME_ITERS, VICTIM_NO_CORRUPT_ITERS, ATTACKER_PROBE_ITERS);
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_control_no_corruption[i]);
    }

    printf("
Positive Control (Deliberate Misprediction: Attacker primes %d, forces S-counter to %d, probes %d):
", ATTACKER_PRIME_ITERS, FORCED_MISPREDICTION_ITERS, ATTACKER_PROBE_ITERS);
    for (int i = 0; i < NUM_TRIALS; i++) {
        printf("%lu
", results_positive_control_mispredict[i]);
    }

    // --- SUMMARY AND PASS/FAIL ANALYSIS ---
    uint64_t avg_baseline = 0;
    uint64_t avg_attack = 0;
    uint64_t avg_no_corruption = 0;
    uint64_t avg_pos_control = 0;

    for (int i = 0; i < NUM_TRIALS; i++) {
        avg_baseline += results_control_baseline[i];
        avg_attack += results_attack_corrupt[i];
        avg_no_corruption += results_control_no_corruption[i];
        avg_pos_control += results_positive_control_mispredict[i];
    }
    avg_baseline /= NUM_TRIALS;
    avg_attack /= NUM_TRIALS;
    avg_no_corruption /= NUM_TRIALS;
    avg_pos_control /= NUM_TRIALS;

    printf("
--- Average Cycle Counts ---
");
    printf("1. Baseline (Attacker primes %d, probes %d): %lu cycles
", ATTACKER_PRIME_ITERS, ATTACKER_PROBE_ITERS, avg_baseline);
    printf("2. Attack (Attacker primes %d, Victim %d, Probes %d): %lu cycles
", ATTACKER_PRIME_ITERS, VICTIM_CORRUPT_ITERS, ATTACKER_PROBE_ITERS, avg_attack);
    printf("3. No Corruption (Attacker primes %d, Victim %d, Probes %d): %lu cycles
", ATTACKER_PRIME_ITERS, VICTIM_NO_CORRUPT_ITERS, ATTACKER_PROBE_ITERS, avg_no_corruption);
    printf("4. Positive Control (Forced misprediction from %d to %d, Probes %d): %lu cycles
", ATTACKER_PRIME_ITERS, FORCED_MISPREDICTION_ITERS, ATTACKER_PROBE_ITERS, avg_pos_control);

    printf("
--- Pass/Fail Analysis ---
");
    int positive_control_passed = 0;
    // Check if positive control shows a significant timing penalty (e.g., at least 25% slower than baseline)
    if (avg_pos_control > avg_baseline * 1.25) { 
        printf("POSITIVE CONTROL PASSED: Deliberate misprediction showed a significant timing penalty (%.2fx baseline). Measurement setup is valid.
", (double)avg_pos_control / avg_baseline);
        positive_control_passed = 1;
    } else {
        printf("POSITIVE CONTROL FAILED: No clear timing difference for deliberate misprediction. Average: %lu vs Baseline: %lu. Measurement setup is invalid. Results inconclusive.
", avg_pos_control, avg_baseline);
    }

    if (positive_control_passed) {
        printf("
Checking Attack Scenario:
");
        // Attack scenario should be significantly slower than baseline and no-corruption control.
        // Using a slightly lower threshold for the attack itself.
        if (avg_attack > avg_baseline * 1.15 && avg_attack > avg_no_corruption * 1.15) { 
            printf("ATTACK SCENARIO PASSED: Detected state corruption. Victim's loop bounds information potentially leaked (%.2fx baseline, %.2fx no-corruption).
", (double)avg_attack / avg_baseline, (double)avg_attack / avg_no_corruption);
        } else {
            printf("ATTACK SCENARIO FAILED: No clear evidence of state corruption. Average: %lu vs Baseline: %lu vs No Corruption: %lu. Results inconclusive.
", avg_attack, avg_baseline, avg_no_corruption);
        }

        printf("
Checking Negative Control (No Corruption):
");
        // The 'no corruption' control should be close to the baseline.
        if (avg_no_corruption < avg_baseline * 1.10) { 
            printf("NEGATIVE CONTROL (No Corruption) PASSED: Victim with same loop count did not cause measurable performance degradation (%.2fx baseline). Expected behavior.
", (double)avg_no_corruption / avg_baseline);
        } else {
            printf("NEGATIVE CONTROL (No Corruption) FAILED: Victim with same loop count caused unexpected performance degradation. Average: %lu vs Baseline: %lu. Potential setup issue.
", avg_no_corruption, avg_baseline);
        }
    } else {
        printf("
ATTACK SCENARIO & NEGATIVE CONTROL (No Corruption): Not evaluated due to Positive Control Failure. Results remain inconclusive.
");
    }

    // Mandatory simulation termination
    tohost = 1;
    while (1) {}

    return 0;
}

// _start function (required for bare-metal RISC-V)
void _start() {
    asm volatile("mv sp, %0" :: "r"(_stack_top)); // Set up stack pointer
    main(); // Call the main function
}

