    // Check if positive control shows a significant timing penalty (e.g., at least 25% slower than baseline)
    if (avg_pos_control > avg_baseline * 1.25) { 
        printf("POSITIVE CONTROL PASSED: Deliberate misprediction showed a significant timing penalty (%.2fx baseline). Measurement setup is valid.\n", (double)avg_pos_control / avg_baseline);
        positive_control_passed = 1;
    } else {
        printf("POSITIVE CONTROL FAILED: No clear timing difference for deliberate misprediction. Average: %lu vs Baseline: %lu. Measurement setup is invalid. Results inconclusive.\n", avg_pos_control, avg_baseline);
    }

    if (positive_control_passed) {
        printf("\nChecking Attack Scenario:\n");
        // Attack scenario should be significantly slower than baseline and no-corruption control.
        // Using a slightly lower threshold for the attack itself.
        if (avg_attack > avg_baseline * 1.15 && avg_attack > avg_no_corruption * 1.15) { 
            printf("ATTACK SCENARIO PASSED: Detected state corruption. Victim's loop bounds information potentially leaked (%.2fx baseline, %.2fx no-corruption).\n", (double)avg_attack / avg_baseline, (double)avg_attack / avg_no_corruption);
        } else {
            printf("ATTACK SCENARIO FAILED: No clear evidence of state corruption. Average: %lu vs Baseline: %lu vs No Corruption: %lu. Results inconclusive.\n", avg_attack, avg_baseline, avg_no_corruption);
        }

        printf("\nChecking Negative Control (No Corruption):\n");
        // The 'no corruption' control should be close to the baseline.
        if (avg_no_corruption < avg_baseline * 1.10) { 
            printf("NEGATIVE CONTROL (No Corruption) PASSED: Victim with same loop count did not cause measurable performance degradation (%.2fx baseline). Expected behavior.\n", (double)avg_no_corruption / avg_baseline);
        } else {
            printf("NEGATIVE CONTROL (No Corruption) FAILED: Victim with same loop count caused unexpected performance degradation. Average: %lu vs Baseline: %lu. Potential setup issue.\n", avg_no_corruption, avg_baseline);
        }
    } else {
        printf("\nATTACK SCENARIO & NEGATIVE CONTROL (No Corruption): Not evaluated due to Positive Control Failure. Results remain inconclusive.\n");
    }

    // Mandatory simulation termination
    tohost = 1;
    while (1) {}

    return 0;
}

